window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b6fe5766c6e985b0"]={"versions": [{"id": "FIG-b6fe5766c6e985b0", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Komponentendiagramm / Schnittstellenspezifikationsdiagramm gemäß den Modellierungsrichtlinien des <em>AUTOSAR BSW UML Model Modeling Guide</em>.\n</li><li><strong>Technischer Zweck:</strong> Formale Definition und semantische Modellierung von BSW-Callbacks (Rückruffunktionen) zwischen Schichten der Classic Platform – exemplifiziert anhand der Interaktion zwischen dem MCAL-Treiber <code>Can</code> (Communication Drivers) und dem Abstraktionsmodul <code>CanIf</code> (Communication Hardware Abstraction Layer).\n</li><li><strong>Funktionale Einordnung:</strong> Veranschaulicht das Umkehren des Aufrufpfads (Inversion of Control) über Schichtgrenzen hinweg: Das unterlagerte Treiber-Modul deklariert die benötigte Callback-Schnittstelle, während das übergeordnete Interface-Modul diese implementiert/realisiert.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Module («module»):</strong>\n<ul class=\"fig-list\"><li><code>CanIf::CanIf</code>: BSW-Modul des CAN-Interfaces (Schicht: BSW Communication Hardware Abstraction). Realisiert die Callback-Funktion.\n</li><li><code>Can::Can</code>: BSW-Modul des CAN-Treibers (Schicht: MCAL). Tritt als Aufrufer des Callbacks auf.\n</li></ul>\n</li><li><strong>Schnittstelle («interface»):</strong>\n<ul class=\"fig-list\"><li><code>Can::CanIf_RxIndication</code>: Im Namensraum des Moduls <code>Can</code> verortete Callback-Schnittstelle (Paketzugehörigkeit kennzeichnet den Anforderer/Aufrufer des Callbacks).\n</li></ul>\n</li><li><strong>Operationen («callback»):</strong>\n<ul class=\"fig-list\"><li><code>+ CanIf_RxIndication(const Can_HwType*, const PduInfoType*)</code>: Normative C-Funktionssignatur für den Empfangsindikator. Übergibt Hardwaredetails (Mailbox/Controller via <code>Can_HwType</code>) und PDU-Nutzdaten/Länge (<code>PduInfoType</code>) als Zeiger auf konstante Daten.\n</li></ul>\n</li><li><strong>Stereotypen &amp; Relationen:</strong>\n<ul class=\"fig-list\"><li><code>«realize»</code> (Abhängigkeitspfeil mit geschlossener, nicht ausgefüllter Spitze): <code>CanIf::CanIf</code> → <code>Can::CanIf_RxIndication</code>. Formalisiert die Implementierungspflicht des Callbacks durch <code>CanIf</code>.\n</li><li><code>«mandatory»</code> (Abhängigkeitspfeil mit offener Spitze): <code>Can::Can</code> → <code>Can::CanIf_RxIndication</code>. Kennzeichnet den Aufruf dieses Callbacks als zwingend erforderlich für den Treiberbetrieb (im Gegensatz zu optionalen Benachrichtigungen wie Fehler-Callbacks).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Hardware-Interrupt (CAN Rx-ISR) oder Polling über <code>Can_MainFunction_Read()</code> im MCAL-Treiber <code>Can</code>.\n</li><li><strong>Ablaufpfad (synchron / unterbrechungsgebunden):</strong>\n<ol class=\"fig-list\"><li>Der CAN-Controller signalisiert erfolgreichen PDU-Empfang in einer Hardware-Receive-Mailbox.\n</li><li>Treiber <code>Can</code> extrahiert die Hardware-Parameter (<code>Mailbox/Hrh</code>, <code>CanId</code>) in eine temporäre Struktur vom Typ <code>Can_HwType</code> und kapselt Payload/DLC in eine Struktur vom Typ <code>PduInfoType</code>.\n</li><li>Treiber <code>Can</code> ruft synchron die realisierte API <code>CanIf_RxIndication()</code> auf.\n</li><li><code>CanIf</code> führt Software-Filtering, Rx-PDU-Routing und Weiterleitung an übergeordnete Module (z. B. PduR, CanTp, CanNm) aus.\n</li></ol>\n</li><li><strong>Kontext:</strong> Typischerweise im ISR-Kontext (CAT2) oder Task-Kontext (Polling); erfordert reentrante und nicht-blockierende Ausführung in <code>CanIf</code>.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Paketierungsregel im AUTOSAR UML-Metamodell:</strong>\n<ul class=\"fig-list\"><li>Callback-Interfaces müssen stets im Package des <em>aufrufenden</em> Moduls definiert werden (hier: <code>Can</code>), da dieses Modul die Schnittstellenanforderung festlegt.\n</li><li>Das verarbeitende Modul (<code>CanIf</code>) importiert bzw. realisiert diese Schnittstelle (<code>«realize»</code>).\n</li></ul>\n</li><li><strong>Treiber-Implementierung (MCAL <code>Can</code>):</strong>\n<ul class=\"fig-list\"><li>Statische Bindung via Header: Der Treiber bindet den Callback typischerweise über <code>#include &quot;CanIf_Cbk.h&quot;</code> ein.\n</li><li>Der Aufruf ist <code>«mandatory»</code>: Fehlt die Realisierung oder Konfiguration im Stack, ist der Treiber nicht linkbar bzw. kann keine empfangenen PDUs zustellen.\n</li></ul>\n</li><li><strong>Stack-Konfiguration (BSW / <code>CanIf</code>):</strong>\n<ul class=\"fig-list\"><li>Die Parameter <code>Can_HwType*</code> und <code>PduInfoType*</code> sind als <code>const</code> deklariert; <code>CanIf</code> darf die Pufferinhalte des Treibers weder modifizieren noch asynchron ohne Kopie weiterverwenden.\n</li><li>Konfigurationsparameter (z. B. <code>CanIfRxPduId</code>, Controller-Zuordnung) müssen exakt auf die vom Treiber übergebenen HRHs (<code>HohType</code>) abgestimmt sein.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-3ff30ba3bfc2deb3", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Komponentendiagramm / Schnittstellenspezifikationsdiagramm gemäß den Modellierungsrichtlinien des <em>AUTOSAR BSW UML Model Modeling Guide</em>.\n</li><li><strong>Technischer Zweck:</strong> Formale Definition und semantische Modellierung von BSW-Callbacks (Rückruffunktionen) zwischen Schichten der Classic Platform – exemplifiziert anhand der Interaktion zwischen dem MCAL-Treiber <code>Can</code> (Communication Drivers) und dem Abstraktionsmodul <code>CanIf</code> (Communication Hardware Abstraction Layer).\n</li><li><strong>Funktionale Einordnung:</strong> Veranschaulicht das Umkehren des Aufrufpfads (Inversion of Control) über Schichtgrenzen hinweg: Das unterlagerte Treiber-Modul deklariert die benötigte Callback-Schnittstelle, während das übergeordnete Interface-Modul diese implementiert/realisiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Module («module»):</strong>\n<ul class=\"fig-list\"><li><code>CanIf::CanIf</code>: BSW-Modul des CAN-Interfaces (Schicht: BSW Communication Hardware Abstraction). Realisiert die Callback-Funktion.\n</li><li><code>Can::Can</code>: BSW-Modul des CAN-Treibers (Schicht: MCAL). Tritt als Aufrufer des Callbacks auf.\n</li></ul>\n</li><li><strong>Schnittstelle («interface»):</strong>\n<ul class=\"fig-list\"><li><code>Can::CanIf_RxIndication</code>: Im Namensraum des Moduls <code>Can</code> verortete Callback-Schnittstelle (Paketzugehörigkeit kennzeichnet den Anforderer/Aufrufer des Callbacks).\n</li></ul>\n</li><li><strong>Operationen («callback»):</strong>\n<ul class=\"fig-list\"><li><code>+ CanIf_RxIndication(const Can_HwType*, const PduInfoType*)</code>: Normative C-Funktionssignatur für den Empfangsindikator. Übergibt Hardwaredetails (Mailbox/Controller via <code>Can_HwType</code>) und PDU-Nutzdaten/Länge (<code>PduInfoType</code>) als Zeiger auf konstante Daten.\n</li></ul>\n</li><li><strong>Stereotypen &amp; Relationen:</strong>\n<ul class=\"fig-list\"><li><code>«realize»</code> (Abhängigkeitspfeil mit geschlossener, nicht ausgefüllter Spitze): <code>CanIf::CanIf</code> → <code>Can::CanIf_RxIndication</code>. Formalisiert die Implementierungspflicht des Callbacks durch <code>CanIf</code>.\n</li><li><code>«mandatory»</code> (Abhängigkeitspfeil mit offener Spitze): <code>Can::Can</code> → <code>Can::CanIf_RxIndication</code>. Kennzeichnet den Aufruf dieses Callbacks als zwingend erforderlich für den Treiberbetrieb (im Gegensatz zu optionalen Benachrichtigungen wie Fehler-Callbacks).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Hardware-Interrupt (CAN Rx-ISR) oder Polling über <code>Can_MainFunction_Read()</code> im MCAL-Treiber <code>Can</code>.\n</li><li><strong>Ablaufpfad (synchron / unterbrechungsgebunden):</strong>\n<ol class=\"fig-list\"><li>Der CAN-Controller signalisiert erfolgreichen PDU-Empfang in einer Hardware-Receive-Mailbox.\n</li><li>Treiber <code>Can</code> extrahiert die Hardware-Parameter (<code>Mailbox/Hrh</code>, <code>CanId</code>) in eine temporäre Struktur vom Typ <code>Can_HwType</code> und kapselt Payload/DLC in eine Struktur vom Typ <code>PduInfoType</code>.\n</li><li>Treiber <code>Can</code> ruft synchron die realisierte API <code>CanIf_RxIndication()</code> auf.\n</li><li><code>CanIf</code> führt Software-Filtering, Rx-PDU-Routing und Weiterleitung an übergeordnete Module (z. B. PduR, CanTp, CanNm) aus.\n</li></ol>\n</li><li><strong>Kontext:</strong> Typischerweise im ISR-Kontext (CAT2) oder Task-Kontext (Polling); erfordert reentrante und nicht-blockierende Ausführung in <code>CanIf</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Paketierungsregel im AUTOSAR UML-Metamodell:</strong>\n<ul class=\"fig-list\"><li>Callback-Interfaces müssen stets im Package des <em>aufrufenden</em> Moduls definiert werden (hier: <code>Can</code>), da dieses Modul die Schnittstellenanforderung festlegt.\n</li><li>Das verarbeitende Modul (<code>CanIf</code>) importiert bzw. realisiert diese Schnittstelle (<code>«realize»</code>).\n</li></ul>\n</li><li><strong>Treiber-Implementierung (MCAL <code>Can</code>):</strong>\n<ul class=\"fig-list\"><li>Statische Bindung via Header: Der Treiber bindet den Callback typischerweise über <code>#include &quot;CanIf_Cbk.h&quot;</code> ein.\n</li><li>Der Aufruf ist <code>«mandatory»</code>: Fehlt die Realisierung oder Konfiguration im Stack, ist der Treiber nicht linkbar bzw. kann keine empfangenen PDUs zustellen.\n</li></ul>\n</li><li><strong>Stack-Konfiguration (BSW / <code>CanIf</code>):</strong>\n<ul class=\"fig-list\"><li>Die Parameter <code>Can_HwType*</code> und <code>PduInfoType*</code> sind als <code>const</code> deklariert; <code>CanIf</code> darf die Pufferinhalte des Treibers weder modifizieren noch asynchron ohne Kopie weiterverwenden.\n</li><li>Konfigurationsparameter (z. B. <code>CanIfRxPduId</code>, Controller-Zuordnung) müssen exakt auf die vom Treiber übergebenen HRHs (<code>HohType</code>) abgestimmt sein.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-b6fe5766c6e985b0", "to": "FIG-3ff30ba3bfc2deb3", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-3ff30ba3bfc2deb3", "to": "FIG-b6fe5766c6e985b0", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
